    global pos
    if nw[pos] == '(':
        pos += 1
        children = [parse_subtree()]
        while nw[pos] == ',':
            pos += 1
            children.append(parse_subtree())
        assert nw[pos] == ')'
        pos += 1
        name = ''
    else:
        start = pos
        while pos < len(nw) and nw[pos] not in ',():;':
            pos += 1
        name = nw[start:pos]
        children = []
    length = 0.0
    if pos < len(nw) and nw[pos] == ':':
